function ensureV14BusinessState(){
  ensureV13State(); let changed=false;
  if(!state.meta.v140BusinessMigratedAt){
    state.sessionRules.defaultPaymentTiming='start';
    state.cashSettings.shiftRequired=true;
    state.meta.v140BusinessMigratedAt=now(); changed=true;
  }
  if(!Array.isArray(state.pricingFormulas)||!state.pricingFormulas.length){state.pricingFormulas=deepClone(V14_DEFAULT_FORMULAS);changed=true}
  const legacyGeneric=new Set(['prod-cola','prod-energy','prod-chips','prod-chocolate']);
  const beforeCount=(state.products||[]).length;state.products=(state.products||[]).filter(p=>!legacyGeneric.has(p.id));if(state.products.length!==beforeCount)changed=true;
  const byId=new Map((state.products||[]).map(p=>[p.id,p]));
  for(const seed of V14_PRODUCT_CATALOG){
    const existing=byId.get(seed.id);
    if(existing){ if(!existing.image||/\.svg$/.test(existing.image)&&!['prod-water','prod-coffee'].includes(existing.id)){existing.image=seed.image;changed=true} }
    else {state.products.push({...seed,enabled:true,cost:0,createdAt:now(),updatedAt:now()});changed=true}
  }
  state.tournaments.forEach(t=>{if(!t.stage)t.stage=t.status==='TERMINÉ'?'finished':t.status==='EN COURS'?'qualifiers':'registration';if(!t.rounds)t.rounds=[];if(!t.winner)t.winner=null});
  state.challenges.forEach(ch=>{if(!ch.stage)ch.stage=ch.status==='TERMINÉ'?'finished':'active';if(!ch.winner)ch.winner=null});
  if(changed)saveState({eventType:'app.v14.business_migrated'});
}
ensureV14BusinessState();

function v14Rate(st,players){return rateFor(st,players)}
function v14FormulaPrice(formula,st,players){
  const raw=v14Rate(st,players)*num(formula.minutes)/60;
  return roundTo(raw*(1-num(formula.discountPct)/100),state.rates.rounding||.5);
}
function v14SessionPlan(d,st){
  const rate=v14Rate(st,d.players),step=state.rates.rounding||.5;
  if(d.billingMode==='budget'){
    const amount=Math.max(step,num(d.budget));
    return {mode:'fixed',minutes:Math.max(1,Math.round(amount/rate*60)),amount:roundTo(amount,step),label:`Budget ${fmtMoney(amount)}`};
  }
  if(d.billingMode==='package'){
    const f=state.pricingFormulas.find(x=>x.id===d.formulaId&&x.enabled!==false);
    if(f)return {mode:'fixed',minutes:num(f.minutes),amount:v14FormulaPrice(f,st,d.players),label:f.name};
    const mins=Math.max(1,num(d.packageMinutes,60));
    const amt=Math.max(0,roundTo(num(d.packageAmount,rate*mins/60),step));
    return {mode:'fixed',minutes:mins,amount:amt,label:'Formule personnalisée'};
  }
  if(d.billingMode==='open'){
    const credit=Math.max(step,num(d.prepaidCredit,st.type==='SIM'?45:rate));
    const mins=Math.max(1,Math.floor(credit/rate*60));
    return {mode:'fixed',minutes:mins,amount:credit,creditMinutes:mins,label:'Libre prépayée'};
  }
  const mins=Math.max(1,num(d.duration,state.sessionRules.defaultDuration));
  const amount=calcAmount(st,mins,d.players,num(d.discountAmount));
  return {mode:'fixed',minutes:mins,amount,label:`${fmtDuration(mins)}`};
}
sessionPlanV13=v14SessionPlan;

