function syncDraftInputsV14(){const d=sheetDraft;if(!d)return;const take=(id,key,obj=null)=>{const el=$(id);if(!el)return;const t=obj?d[obj]:d;t[key]=el.type==='number'?num(el.value):el.value};take('gameTitleV13','gameTitle');take('clientSearchV13','clientQuery');take('newFirstV13','firstName','newClient');take('newLastV13','lastName','newClient');take('newPhoneV13','phone','newClient');take('newEmailV13','email','newClient');take('sessionNoteV13','note');take('v14Duration','duration');take('v14Budget','budget');take('v14PackageMinutes','packageMinutes');take('v14PackageAmount','packageAmount');take('v14PrepaidCredit','prepaidCredit');take('v14PaymentMethod','paymentMethod')}
