  $('gameCategoryV13').onchange=e=>{syncDraftInputsV14();d.gameCategory=e.target.value;d.gameTitle=gameInfo(d.gameCategory).title;drawStartSheet()};$('gameTitleV13').oninput=e=>d.gameTitle=e.target.value;if($('sessionNoteV13'))$('sessionNoteV13').oninput=e=>d.note=e.target.value;
