function v14RestoreCriticalClients(){
  try{
    if(!native||!native.getClientsBackupJson)return;
    const raw=native.getClientsBackupJson();if(!raw)return;const backup=JSON.parse(raw);if(!Array.isArray(backup)||!backup.length)return;
    let changed=false;const keys=new Set((state.clients||[]).flatMap(c=>[c.id,c.phone].filter(Boolean).map(String)));
    for(const c of backup){if(!c||(!c.id&&!c.phone))continue;const found=(c.id&&keys.has(String(c.id)))||(c.phone&&keys.has(String(c.phone)));if(!found){state.clients.push(c);if(c.id)keys.add(String(c.id));if(c.phone)keys.add(String(c.phone));changed=true}}
    if(changed)saveState({eventType:'clients.critical_restore',payload:{count:backup.length}});
  }catch(_e){}
}

function settingsSessions(){return `<div class="card"><div class="critical-alert-v14"><b>PAIEMENT AVANT JEU VERROUILLÉ</b><small>Toutes les sessions, prolongations et recharges sont encaissées avant consommation. Une session libre est un crédit prépayé converti en temps.</small></div><div class="field-inline"><label>Durée par défaut</label><input id="defaultDuration" type="number" min="1" max="720" value="${state.sessionRules.defaultDuration}"></div><div class="field-inline"><label>Alerte avant fin</label><input id="warningMinutes" type="number" min="1" max="60" value="${state.sessionRules.warningMinutes}"></div><div class="field"><label>Durées rapides · minutes</label><input id="quickDurations" value="${state.sessionRules.quickDurations.join(', ')}"></div><div class="field"><label>Budgets rapides · DH</label><input id="quickBudgetsV13" value="${(state.sessionRules.quickBudgets||[20,30,50,100]).join(', ')}"></div><label class="switch-row"><div class="switch-copy"><b>Libre prépayée</b><small>Crédit encaissé d’abord, puis converti automatiquement en temps.</small></div><span class="switch"><input id="allowOpen" type="checkbox" ${state.sessionRules.allowOpenSession?'checked':''}><i></i></span></label><label class="switch-row"><div class="switch-copy"><b>Pause / reprise</b></div><span class="switch"><input id="allowPause" type="checkbox" ${state.sessionRules.allowPause?'checked':''}><i></i></span></label><label class="switch-row"><div class="switch-copy"><b>Fin automatique</b></div><span class="switch"><input id="autoFinish" type="checkbox" ${state.sessionRules.autoFinish?'checked':''}><i></i></span></label><div class="field"><label>Paiement par défaut</label><select id="paymentTiming"><option value="start" selected>Avant le jeu — obligatoire</option></select></div><button class="primary full" id="saveSessionRules">Enregistrer</button></div>`}

function settingsNotifications(){return `<div class="critical-alert-v14"><b>ALERTES NATIVES CRITIQUES</b><small>La V1.4 programme trois alarmes Android natives : bientôt terminé, temps écoulé et dépassement critique. Elles sont reprogrammées après redémarrage du téléphone ou mise à jour de l’app.</small></div><div class="card"><label class="switch-row"><div class="switch-copy"><b>Son</b><small>Bip dans l’app au premier plan.</small></div><span class="switch"><input id="soundEnabled" type="checkbox" ${state.sessionRules.sound?'checked':''}><i></i></span></label><label class="switch-row"><div class="switch-copy"><b>Vibration</b><small>Retour tactile local.</small></div><span class="switch"><input id="vibrateEnabled" type="checkbox" ${state.sessionRules.vibrate?'checked':''}><i></i></span></label><label class="switch-row"><div class="switch-copy"><b>Garder l'écran allumé</b><small>Optionnel pendant l’exploitation.</small></div><span class="switch"><input id="keepScreen" type="checkbox" ${state.ui.keepScreenOn?'checked':''}><i></i></span></label><button class="primary full" id="saveNotifications">Enregistrer</button><button class="secondary full" id="testAlert" style="margin-top:8px">Tester la notification native</button></div>`}

function settingsPricing(){return `<div class="critical-alert-v14"><b>MOTEUR TARIFAIRE UNIQUE</b><small>Temps → prix, budget → temps, formule → prix remisé et crédit libre → autonomie. Les tarifs servent à tous les calculs de la salle.</small></div><div class="card"><div class="grid-2"><div class="field"><label>PS5 Solo · DH/h</label><input id="rateSolo" type="number" min="0" step="0.5" value="${state.rates.ps5Solo}"></div><div class="field"><label>PS5 Duo · DH/h</label><input id="rateDuo" type="number" min="0" step="0.5" value="${state.rates.ps5Duo}"></div></div><div class="grid-2"><div class="field"><label>SIM RACING VIP · DH/h</label><input id="rateSim" type="number" min="0" step="0.5" value="${state.rates.sim}"></div><div class="field"><label>Arrondi · DH</label><select id="rounding">${[0,.5,1,2,5].map(x=>`<option value="${x}" ${num(state.rates.rounding)===x?'selected':''}>${x||'Aucun'}</option>`).join('')}</select></div></div><div class="field"><label>Minimum · DH</label><input id="minimumCharge" type="number" min="0" step="0.5" value="${state.rates.minimumCharge||0}"></div><button class="primary full" id="savePricing">Enregistrer</button></div><div class="info-card">Les formules sont gérées dans Commerce → Tarifs. Une modification n’altère jamais les sessions déjà démarrées.</div>`}

function renderPricing(){
  ensureV14BusinessState();const rateCards=()=>`<div class="pricing-live-v14"><div><small>PS5 SOLO</small><b id="v14PrevSolo">${fmtMoney(state.rates.ps5Solo)}/h</b></div><div><small>PS5 DUO</small><b id="v14PrevDuo">${fmtMoney(state.rates.ps5Duo)}/h</b></div><div><small>SIM RACING VIP</small><b id="v14PrevSim">${fmtMoney(state.rates.sim)}/h</b></div></div>`;
  let html=pageTitle('Tarifs & Formules','Moteur dynamique central : chaque champ recalcule immédiatement les montants.',`<button class="primary orange-btn compact-btn" id="v14AddFormula">＋ Formule</button>`);html+=rateCards();
  html+=`<div class="card"><div class="grid-2"><div class="field"><label>PS5 Solo · DH/h</label><input id="v14PriceSolo" type="number" min="0" step="0.5" value="${state.rates.ps5Solo}"></div><div class="field"><label>PS5 Duo · DH/h</label><input id="v14PriceDuo" type="number" min="0" step="0.5" value="${state.rates.ps5Duo}"></div></div><div class="grid-2"><div class="field"><label>SIM VIP · DH/h</label><input id="v14PriceSim" type="number" min="0" step="0.5" value="${state.rates.sim}"></div><div class="field"><label>Arrondi · DH</label><select id="v14PriceRound">${[0,.5,1,2,5].map(x=>`<option value="${x}" ${num(state.rates.rounding)===x?'selected':''}>${x||'Aucun'}</option>`).join('')}</select></div></div><button class="primary orange-btn full" id="v14SaveRates">Enregistrer les tarifs de base</button></div>`;
  html+=`<div class="section-title"><h2>FORMULES</h2><span>${state.pricingFormulas.length}</span></div><div class="list">${state.pricingFormulas.length?state.pricingFormulas.map(f=>`<button class="formula-admin-v14" data-v14-edit-formula="${f.id}"><div><b>${esc(f.name)}</b><small>${fmtDuration(f.minutes)} · remise ${num(f.discountPct)}% · ${f.enabled===false?'INACTIVE':'ACTIVE'}</small></div><strong>Solo ${fmtMoney(v14FormulaPrice(f,{type:'PS5'},1))}</strong></button>`).join(''):'<div class="empty-v12">Aucune formule.</div>'}</div>`;
  $('view').innerHTML=html;
  const live=()=>{const a=num($('v14PriceSolo')?.value),b=num($('v14PriceDuo')?.value),c=num($('v14PriceSim')?.value);if($('v14PrevSolo'))$('v14PrevSolo').textContent=`${fmtMoney(a)}/h`;if($('v14PrevDuo'))$('v14PrevDuo').textContent=`${fmtMoney(b)}/h`;if($('v14PrevSim'))$('v14PrevSim').textContent=`${fmtMoney(c)}/h`};['v14PriceSolo','v14PriceDuo','v14PriceSim'].forEach(id=>{const el=$(id);if(el)el.oninput=live});
  $('v14SaveRates').onclick=()=>{state.rates.ps5Solo=Math.max(0,num($('v14PriceSolo').value));state.rates.ps5Duo=Math.max(0,num($('v14PriceDuo').value));state.rates.sim=Math.max(0,num($('v14PriceSim').value));state.rates.rounding=num($('v14PriceRound').value,.5);saveState({eventType:'pricing.updated'});renderPricing();toast('Tarifs enregistrés')};$('v14AddFormula').onclick=()=>openFormulaV14();document.querySelectorAll('[data-v14-edit-formula]').forEach(b=>b.onclick=()=>openFormulaV14(state.pricingFormulas.find(f=>f.id===b.dataset.v14EditFormula)));
}
function openFormulaV14(f=null){
  const d=f||{name:'',minutes:60,discountPct:0,enabled:true};const preview=(minutes=d.minutes,discount=d.discountPct)=>{const make=r=>roundTo(r*num(minutes)/60*(1-num(discount)/100),state.rates.rounding||.5);return {solo:make(state.rates.ps5Solo),duo:make(state.rates.ps5Duo),sim:make(state.rates.sim)}};const pv=preview();showModal(`<h3>${f?'Modifier':'Nouvelle'} formule</h3><div class="field"><label>Nom</label><input id="v14FormulaName" value="${esc(d.name)}"></div><div class="grid-2"><div class="field"><label>Durée · minutes</label><input id="v14FormulaMinutes" type="number" min="1" value="${num(d.minutes,60)}"></div><div class="field"><label>Remise · %</label><input id="v14FormulaDiscount" type="number" min="0" max="100" step="0.5" value="${num(d.discountPct)}"></div></div><div class="formula-preview-v14"><div><small>PS5 Solo</small><b id="v14FPrevSolo">${fmtMoney(pv.solo)}</b></div><div><small>PS5 Duo</small><b id="v14FPrevDuo">${fmtMoney(pv.duo)}</b></div><div><small>SIM VIP</small><b id="v14FPrevSim">${fmtMoney(pv.sim)}</b></div></div><label class="switch-row"><div class="switch-copy"><b>Formule active</b><small>Visible lors de l’ouverture d’une session.</small></div><span class="switch"><input id="v14FormulaEnabled" type="checkbox" ${d.enabled===false?'':'checked'}><i></i></span></label><div class="modal-actions"><button class="ghost" id="modalCancel">Annuler</button>${f?'<button class="danger" id="v14FormulaDelete">Supprimer</button>':''}<button class="primary" id="modalOk">Enregistrer</button></div>`);
  const live=()=>{const x=preview(num($('v14FormulaMinutes').value),num($('v14FormulaDiscount').value));$('v14FPrevSolo').textContent=fmtMoney(x.solo);$('v14FPrevDuo').textContent=fmtMoney(x.duo);$('v14FPrevSim').textContent=fmtMoney(x.sim)};$('v14FormulaMinutes').oninput=live;$('v14FormulaDiscount').oninput=live;$('modalCancel').onclick=closeModal;if($('v14FormulaDelete'))$('v14FormulaDelete').onclick=()=>{state.pricingFormulas=state.pricingFormulas.filter(x=>x.id!==f.id);saveState({eventType:'pricing.formula_deleted',entityId:f.id});closeModal();renderPricing()};$('modalOk').onclick=()=>{const data={name:$('v14FormulaName').value.trim(),minutes:Math.max(1,num($('v14FormulaMinutes').value,60)),discountPct:clamp(num($('v14FormulaDiscount').value),0,100),enabled:$('v14FormulaEnabled').checked,updatedAt:now()};if(!data.name)return toast('Nom obligatoire');if(f)Object.assign(f,data);else state.pricingFormulas.push({id:uid('formula'),...data,createdAt:now()});saveState({eventType:f?'pricing.formula_updated':'pricing.formula_created',entityId:f?.id,payload:data});closeModal();renderPricing();toast('Formule enregistrée')}
}

function v14ShiftRevenue(sh=null){const sid=sh?.id||null,match=x=>!sid||x.shiftId===sid;const game=state.payments.filter(match).reduce((a,p)=>a+num(p.amount),0),prod=state.orders.filter(o=>o.status==='paid'&&match(o)).reduce((a,o)=>a+num(o.total),0),other=state.cashEntries.filter(e=>e.type==='revenue'&&match(e)).reduce((a,e)=>a+num(e.amount),0);return {game,prod,other,total:game+prod+other}}
function v14ShiftExpected(sh){if(!sh)return 0;const cashPays=state.payments.filter(p=>p.shiftId===sh.id&&p.method==='cash').reduce((a,p)=>a+num(p.amount),0),cashOrders=state.orders.filter(o=>o.status==='paid'&&o.shiftId===sh.id&&(o.paymentMethod||'cash')==='cash').reduce((a,o)=>a+num(o.total),0),entries=state.cashEntries.filter(e=>e.shiftId===sh.id),cashRev=entries.filter(e=>e.type==='revenue'&&(e.method||'cash')==='cash').reduce((a,e)=>a+num(e.amount),0),cashIn=entries.filter(e=>e.type==='cash_in').reduce((a,e)=>a+num(e.amount),0),cashOut=entries.filter(e=>e.type==='expense'&&(e.method||'cash')==='cash').reduce((a,e)=>a+num(e.amount),0);return roundTo(num(sh.openingCash)+cashPays+cashOrders+cashRev+cashIn-cashOut,state.rates.rounding||.5)}
function v14MethodTotalsToday(){const map={};for(const m of enabledMethods())map[m.id]=0;todayPayments().forEach(p=>map[p.method]=(map[p.method]||0)+num(p.amount));state.orders.filter(o=>o.status==='paid'&&dateKey(o.paidAt)===dateKey()).forEach(o=>map[o.paymentMethod||'cash']=(map[o.paymentMethod||'cash']||0)+num(o.total));state.cashEntries.filter(e=>e.type==='revenue'&&dateKey(e.at)===dateKey()).forEach(e=>map[e.method||'cash']=(map[e.method||'cash']||0)+num(e.amount));return map}
function renderCash(){
  ensureV14BusinessState();const sh=currentShift(),methods=v14MethodTotalsToday(),sessionRev=todayRevenue(),orderRev=state.orders.filter(o=>o.status==='paid'&&dateKey(o.paidAt)===dateKey()).reduce((a,o)=>a+num(o.total),0),entries=state.cashEntries.filter(e=>dateKey(e.at)===dateKey()),otherRev=entries.filter(e=>e.type==='revenue').reduce((a,e)=>a+num(e.amount),0),expenses=entries.filter(e=>e.type==='expense').reduce((a,e)=>a+num(e.amount),0),cashIn=entries.filter(e=>e.type==='cash_in').reduce((a,e)=>a+num(e.amount),0),ca=sessionRev+orderRev+otherRev,net=ca-expenses,expected=sh?v14ShiftExpected(sh):0;
  let html=pageTitle('Caisse · Snacks & Drinks','Vraie caisse : ventes, moyens de paiement, mouvements, dépenses, stock et clôture.',sh?`<button class="danger compact-btn" id="closeShiftBtn">Clôturer</button>`:`<button class="primary orange-btn compact-btn" id="openShiftBtn">Ouvrir caisse</button>`);html+=premiumKpis([{label:'CA jour',value:fmtMoney(ca),tone:'orange'},{label:'Jeu',value:fmtMoney(sessionRev),tone:'green'},{label:'Snacks / drinks',value:fmtMoney(orderRev),tone:'amber'},{label:'Net après dépenses',value:fmtMoney(net),tone:net>=0?'green':'red'}]);
  html+=`<div class="cash-status-v14 ${sh?'open':'closed'}"><div><span>${sh?'SHIFT OUVERT':'SHIFT FERMÉ'}</span><b>${sh?`Depuis ${fmtTime(sh.openedAt)} · fond ${fmtMoney(sh.openingCash)}`:'Ouvre la caisse avant toute vente'}</b></div>${sh?`<strong>${fmtMoney(expected)} espèces</strong>`:''}</div>`;
  html+=`<div class="section-title"><h2>VENTE RAPIDE · SNACKS & DRINKS</h2><span>Paiement en avance</span></div><div class="pos-layout-v14"><div class="pos-products-v14">${state.products.filter(p=>p.enabled!==false).map(p=>`<button class="pos-product-v14 ${num(p.stock)<=0?'soldout':''}" data-pos-add="${p.id}" ${num(p.stock)<=0?'disabled':''}><img src="${esc(productImageV13(p))}" alt="${esc(p.name)}"><div><b>${esc(p.name)}</b><small>Stock ${num(p.stock)}</small><strong>${fmtMoney(p.price)}</strong></div></button>`).join('')}</div><div class="pos-cart-v14"><div class="pos-cart-head"><span>PANIER</span><b>${fmtMoney(v14CartTotal())}</b></div><div>${v14CartItems().length?v14CartItems().map(x=>`<div class="pos-line-v14"><span>${esc(x.p.name)}</span><div><button data-pos-minus="${x.p.id}">−</button><b>${x.qty}</b><button data-pos-plus="${x.p.id}">+</button></div><strong>${fmtMoney(x.qty*x.p.price)}</strong></div>`).join(''):'<div class="empty-v12">Touchez un produit pour l’ajouter.</div>'}</div><div class="field"><label>Moyen de paiement</label><select id="v14PosMethod">${enabledMethods().map(m=>`<option value="${m.id}" ${m.id===state.cashSettings.defaultMethod?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><button class="primary orange-btn full" id="v14Checkout" ${!v14CartItems().length||!sh?'disabled':''}>Encaisser ${fmtMoney(v14CartTotal())}</button></div></div>`;
  html+=`<div class="section-title"><h2>COMPTABILITÉ DU JOUR</h2><span>CA ≠ fond de caisse</span></div><div class="cash-method-grid-v14">${enabledMethods().map(m=>`<div><small>${esc(m.name)}</small><b>${fmtMoney(methods[m.id]||0)}</b></div>`).join('')}</div><div class="action-grid v14-cash-actions"><button class="secondary" id="addRevenueBtn">＋ Autre recette</button><button class="secondary" id="addCashInBtn">＋ Apport / monnaie</button><button class="secondary" id="addExpenseBtn">− Dépense</button></div><div class="info-card">Apport / monnaie augmente les espèces physiques mais ne compte jamais dans le chiffre d’affaires. Les dépenses réduisent le net et la caisse seulement si elles sont payées en espèces.</div>`;
  const movements=[...todayPayments().map(p=>({at:p.at,label:`Jeu · ${stationLabel(sessionById(p.sessionId)?.stationId)}`,sub:paymentMethodName(p.method),amount:p.amount})),...state.orders.filter(o=>o.status==='paid'&&dateKey(o.paidAt)===dateKey()).map(o=>({at:o.paidAt,label:o.sessionId?'Snack session':'Vente comptoir',sub:paymentMethodName(o.paymentMethod||'cash'),amount:o.total})),...entries.map(e=>({at:e.at,label:e.label,sub:e.type==='cash_in'?'Apport caisse':e.type==='expense'?`Dépense · ${paymentMethodName(e.method||'cash')}`:`Recette · ${paymentMethodName(e.method||'cash')}`,amount:e.type==='expense'?-e.amount:e.amount}))].sort((a,b)=>b.at-a.at).slice(0,60);html+=`<div class="section-title"><h2>JOURNAL DE CAISSE</h2><span>${movements.length}</span></div>${movements.length?`<div class="list">${movements.map(m=>`<div class="row-card"><div class="row-main"><div class="row-title">${esc(m.label)}</div><div class="row-meta">${fmtTime(m.at)} · ${esc(m.sub)}</div></div><div class="money ${m.amount<0?'red':'green'}">${m.amount<0?'−':'+'}${fmtMoney(Math.abs(m.amount))}</div></div>`).join('')}</div>`:'<div class="empty-v12">Aucun mouvement.</div>'}`;
  $('view').innerHTML=html;if($('openShiftBtn'))$('openShiftBtn').onclick=openShiftModal;if($('closeShiftBtn'))$('closeShiftBtn').onclick=closeShiftModal;$('addRevenueBtn').onclick=()=>openCashEntry('revenue');$('addCashInBtn').onclick=()=>openCashEntry('cash_in');$('addExpenseBtn').onclick=()=>openCashEntry('expense');document.querySelectorAll('[data-pos-add]').forEach(b=>b.onclick=()=>{V14_POS_CART[b.dataset.posAdd]=Math.min(num(state.products.find(p=>p.id===b.dataset.posAdd)?.stock),num(V14_POS_CART[b.dataset.posAdd])+1);renderCash()});document.querySelectorAll('[data-pos-plus]').forEach(b=>b.onclick=()=>{V14_POS_CART[b.dataset.posPlus]=Math.min(num(state.products.find(p=>p.id===b.dataset.posPlus)?.stock),num(V14_POS_CART[b.dataset.posPlus])+1);renderCash()});document.querySelectorAll('[data-pos-minus]').forEach(b=>b.onclick=()=>{V14_POS_CART[b.dataset.posMinus]=Math.max(0,num(V14_POS_CART[b.dataset.posMinus])-1);renderCash()});if($('v14Checkout'))$('v14Checkout').onclick=()=>v14CheckoutPos($('v14PosMethod').value);
}
function openShiftModal(){if(currentShift())return toast('Une caisse est déjà ouverte');showModal(`<h3>Ouvrir la caisse</h3><p>Le fond de départ n’est pas du chiffre d’affaires : il sert uniquement au calcul des espèces attendues.</p><div class="field"><label>Fond de caisse · DH</label><input id="openingCash" type="number" min="0" step="0.5" value="0"></div><div class="field"><label>Responsable / note</label><input id="shiftNote" placeholder="Optionnel"></div><div class="modal-actions"><button class="ghost" id="modalCancel">Annuler</button><button class="primary" id="modalOk">Ouvrir maintenant</button></div>`);$('modalCancel').onclick=closeModal;$('modalOk').onclick=()=>{const sh={id:uid('shift'),openedAt:now(),closedAt:null,status:'open',openingCash:Math.max(0,num($('openingCash').value)),closingCash:null,expectedCash:null,difference:null,note:$('shiftNote').value.trim(),appVersion:APP_VERSION};state.shifts.push(sh);saveState({eventType:'shift.opened',entityId:sh.id,payload:sh});closeModal();renderCash();toast('Caisse ouverte')}}
function openCashEntry(type){const cfg=type==='expense'?{title:'Enregistrer une dépense',def:'Dépense',help:'Réduit le résultat net.'}:type==='cash_in'?{title:'Ajouter un apport / monnaie',def:'Apport caisse',help:'Augmente les espèces physiques sans augmenter le CA.'}:{title:'Enregistrer une autre recette',def:'Autre recette',help:'Compte dans le chiffre d’affaires.'};showModal(`<h3>${cfg.title}</h3><p>${cfg.help}</p><div class="field"><label>Libellé</label><input id="entryLabel" placeholder="${cfg.def}"></div><div class="field"><label>Montant · DH</label><input id="entryAmount" type="number" min="0.5" step="0.5"></div>${type==='cash_in'?'':`<div class="field"><label>Moyen de paiement</label><select id="entryMethod">${enabledMethods().map(m=>`<option value="${m.id}" ${m.id===state.cashSettings.defaultMethod?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div>`}<div class="field"><label>Note</label><input id="entryNote" placeholder="Optionnel"></div><div class="modal-actions"><button class="ghost" id="modalCancel">Annuler</button><button class="primary" id="modalOk">Enregistrer</button></div>`);$('modalCancel').onclick=closeModal;$('modalOk').onclick=()=>{const amount=num($('entryAmount').value);if(amount<=0)return toast('Montant obligatoire');const e={id:uid('cash'),type,amount,label:$('entryLabel').value.trim()||cfg.def,note:$('entryNote').value.trim(),method:type==='cash_in'?'cash':$('entryMethod').value,at:now(),shiftId:currentShift()?.id||null};state.cashEntries.push(e);saveState({eventType:`cash.${type}`,entityId:e.id,payload:e});closeModal();renderCash();toast('Mouvement enregistré')}}
function closeShiftModal(){const sh=currentShift();if(!sh)return;const expected=v14ShiftExpected(sh),rev=v14ShiftRevenue(sh),entries=state.cashEntries.filter(e=>e.shiftId===sh.id),expenses=entries.filter(e=>e.type==='expense').reduce((a,e)=>a+num(e.amount),0),net=rev.total-expenses;showModal(`<h3>Clôture comptable</h3><div class="cash-close-summary-v14"><div><span>Fond départ</span><b>${fmtMoney(sh.openingCash)}</b></div><div><span>CA jeu</span><b>${fmtMoney(rev.game)}</b></div><div><span>CA produits</span><b>${fmtMoney(rev.prod)}</b></div><div><span>Autres recettes</span><b>${fmtMoney(rev.other)}</b></div><div><span>Dépenses</span><b class="red">−${fmtMoney(expenses)}</b></div><div><span>Net opérationnel</span><b>${fmtMoney(net)}</b></div><div class="total"><span>Espèces attendues</span><b>${fmtMoney(expected)}</b></div></div><div class="field"><label>Espèces réellement comptées</label><input id="closingCash" type="number" min="0" step="0.5" value="${expected}"></div><div class="field"><label>Note clôture</label><input id="closingNote" placeholder="Obligatoire si écart"></div><div class="modal-actions"><button class="ghost" id="modalCancel">Annuler</button><button class="danger" id="modalOk">Clôturer définitivement</button></div>`);$('modalCancel').onclick=closeModal;$('modalOk').onclick=()=>{const counted=num($('closingCash').value),diff=roundTo(counted-expected,.5),note=$('closingNote').value.trim();if(Math.abs(diff)>.001&&!note)return toast('Explique l’écart dans la note');sh.closedAt=now();sh.status='closed';sh.expectedCash=expected;sh.closingCash=counted;sh.difference=diff;sh.closingNote=note;sh.revenue=rev.total;sh.expenses=expenses;sh.net=net;saveState({eventType:'shift.closed',entityId:sh.id,payload:sh});closeModal();renderCash();toast(`Clôture terminée · écart ${fmtMoney(diff)}`)}}

/* Upgrade legacy manual cash entries and tournament registration accounting. */
for(const e of state.cashEntries||[]){if(e.type==='income')e.type=/inscription tournoi/i.test(e.label||'')?'revenue':'cash_in';if(!e.method)e.method='cash'}
state.sessionRules.defaultPaymentTiming='start';
v14RestoreCriticalClients();
saveState();
renderView();
